create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',role text not null check(role in('doctor','receptionist')) default 'receptionist',created_at timestamptz not null default now());
create table if not exists public.inventory_items(id uuid primary key default gen_random_uuid(),name text not null,category text not null default 'General',unit text not null default 'pcs',min_stock numeric not null default 0 check(min_stock>=0),created_at timestamptz not null default now());
create table if not exists public.stock_batches(id uuid primary key default gen_random_uuid(),item_id uuid not null references public.inventory_items(id),batch_no text,quantity numeric not null check(quantity>0),remaining numeric not null check(remaining>=0),purchase_date date not null default current_date,expiry_date date,supplier text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.stock_movements(id uuid primary key default gen_random_uuid(),item_id uuid not null references public.inventory_items(id),batch_id uuid references public.stock_batches(id),movement_type text not null check(movement_type in('purchase','usage','adjustment')),quantity numeric not null check(quantity>0),movement_date timestamptz not null default now(),patient_or_reference text,notes text,created_by uuid references auth.users(id));
create or replace function public.current_app_role() returns text language sql stable security definer set search_path=public as $$select role from public.profiles where id=auth.uid()$$;
alter table public.profiles enable row level security;alter table public.inventory_items enable row level security;alter table public.stock_batches enable row level security;alter table public.stock_movements enable row level security;
create policy "profile self or doctor read" on public.profiles for select to authenticated using(id=auth.uid() or public.current_app_role()='doctor');create policy "doctor manage profiles" on public.profiles for all to authenticated using(public.current_app_role()='doctor') with check(public.current_app_role()='doctor');
create policy "staff read items" on public.inventory_items for select to authenticated using(true);create policy "staff add items" on public.inventory_items for insert to authenticated with check(public.current_app_role() in('doctor','receptionist'));create policy "staff update items" on public.inventory_items for update to authenticated using(public.current_app_role() in('doctor','receptionist'));create policy "doctor delete items" on public.inventory_items for delete to authenticated using(public.current_app_role()='doctor');
create policy "staff read batches" on public.stock_batches for select to authenticated using(true);create policy "staff add batches" on public.stock_batches for insert to authenticated with check(public.current_app_role() in('doctor','receptionist'));create policy "doctor update batches" on public.stock_batches for update to authenticated using(public.current_app_role()='doctor');create policy "doctor delete batches" on public.stock_batches for delete to authenticated using(public.current_app_role()='doctor');
create policy "staff read movements" on public.stock_movements for select to authenticated using(true);create policy "staff add movements" on public.stock_movements for insert to authenticated with check(public.current_app_role() in('doctor','receptionist'));create policy "doctor delete movements" on public.stock_movements for delete to authenticated using(public.current_app_role()='doctor');
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,full_name,role) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),'receptionist');return new;end;$$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
-- Promote the clinic owner after first signup: update public.profiles set role='doctor' where id='AUTH_USER_UUID';
create or replace function public.record_usage(p_item_id uuid,p_quantity numeric,p_reference text default null,p_notes text default null) returns void language plpgsql security definer set search_path=public as $$declare need numeric:=p_quantity;b record;take_qty numeric;begin if auth.uid() is null or public.current_app_role() not in('doctor','receptionist') then raise exception 'Not authorized';end if;if p_quantity<=0 then raise exception 'Quantity must be positive';end if;for b in select id,remaining from public.stock_batches where item_id=p_item_id and remaining>0 and(expiry_date is null or expiry_date>=current_date) order by expiry_date nulls last,purchase_date,created_at for update loop exit when need<=0;take_qty:=least(need,b.remaining);update public.stock_batches set remaining=remaining-take_qty where id=b.id;insert into public.stock_movements(item_id,batch_id,movement_type,quantity,patient_or_reference,notes,created_by) values(p_item_id,b.id,'usage',take_qty,p_reference,p_notes,auth.uid());need:=need-take_qty;end loop;if need>0 then raise exception 'Insufficient unexpired stock';end if;end;$$;grant execute on function public.record_usage(uuid,numeric,text,text) to authenticated;
